// Android-side Capacitor plugin for Этап 2b — see ../README.md for build
// instructions and current status. Source of truth: copy this file into
// android/app/src/main/java/com/simpledimple/app/VpnTunnelPlugin.kt (the
// android/ project is generated by `npx cap add android` and regenerating it
// would wipe local edits there).
//
// JS-side contract lives in frontend/src/lib/vpnTunnel.ts (not mobile/) —
// Capacitor bundles frontend/dist as its webDir, so that's the code that
// actually ships and calls into this plugin by name ("VpnTunnel").

package com.simpledimple.app

import android.app.Activity
import android.content.Intent
import android.net.VpnService
import android.os.Build
import androidx.activity.result.ActivityResult
import com.getcapacitor.JSObject
import com.getcapacitor.Plugin
import com.getcapacitor.PluginCall
import com.getcapacitor.PluginMethod
import com.getcapacitor.annotation.ActivityCallback
import com.getcapacitor.annotation.CapacitorPlugin
import java.io.File

@CapacitorPlugin(name = "VpnTunnel")
class VpnTunnelPlugin : Plugin() {

    private var pendingTunnelParams: TunnelParams? = null

    @PluginMethod
    fun connect(call: PluginCall) {
        val tunnelParams = parseTunnelParams(call) ?: return

        // Android VPN consent: VpnService.prepare() returns a non-null Intent the
        // first time (or after the user revokes a prior grant) an app on this
        // device requests VPN access. That Intent has to be launched for the user
        // to approve before any tunnel can come up; startActivityForResult here is
        // Capacitor's own call-persisting helper, so `call` is handed back as-is
        // to the @ActivityCallback method below once the user responds.
        val consentIntent = VpnService.prepare(context)
        if (consentIntent != null) {
            pendingTunnelParams = tunnelParams
            startActivityForResult(call, consentIntent, "onVpnConsentResult")
            return
        }

        startTunnel(call, tunnelParams)
    }

    @ActivityCallback
    private fun onVpnConsentResult(call: PluginCall?, result: ActivityResult) {
        if (call == null) {
            // Capacitor could not restore the original call (e.g. process was
            // killed while the consent activity was open) — nothing to resolve.
            pendingTunnelParams = null
            return
        }

        if (result.resultCode != Activity.RESULT_OK) {
            pendingTunnelParams = null
            call.reject("User declined the VPN permission request")
            return
        }

        val tunnelParams = pendingTunnelParams ?: parseTunnelParams(call) ?: return
        pendingTunnelParams = null
        startTunnel(call, tunnelParams)
    }

    // config shape is ConnectionConfigSummary from frontend/src/types — top-level
    // uri/endpointId/protocol/security plus a nested `params` object with the
    // actual VLESS+REALITY fields.
    private fun parseTunnelParams(call: PluginCall): TunnelParams? {
        val config = call.getObject("config")
        if (config == null) {
            call.reject("config is required")
            return null
        }

        val params = config.getJSObject("params")
        if (params == null) {
            call.reject("config.params is required")
            return null
        }

        val tunnelParams = TunnelParams(
            uuid = params.optString("uuid", ""),
            address = params.optString("address", ""),
            port = params.optInt("port", 0),
            flow = params.optString("flow", ""),
            sni = params.optString("sni", ""),
            fingerprint = params.optString("fingerprint", ""),
            publicKey = params.optString("publicKey", ""),
            shortId = params.optString("shortId", "")
        )

        if (tunnelParams.address.isEmpty() || tunnelParams.port == 0) {
            call.reject("config.params.address and config.params.port are required")
            return null
        }
        if (tunnelParams.uuid.isEmpty() || tunnelParams.publicKey.isEmpty()) {
            call.reject("config.params.uuid and config.params.publicKey are required")
            return null
        }

        return tunnelParams
    }

    private fun startTunnel(call: PluginCall, tunnelParams: TunnelParams) {
        val configJson = buildXrayConfig(tunnelParams)
        val configFile = File(context.filesDir, "xray_tunnel_config.json")
        try {
            configFile.writeText(configJson)
        } catch (e: Exception) {
            call.reject("failed to write Xray config: ${e.message}")
            return
        }

        VpnTunnelPlugin.pendingConnectCall = call
        val intent = Intent(context, SimpleDimpleVpnService::class.java).apply {
            action = SimpleDimpleVpnService.ACTION_START
            putExtra(SimpleDimpleVpnService.EXTRA_CONFIG_PATH, configFile.absolutePath)
        }
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            context.startForegroundService(intent)
        } else {
            context.startService(intent)
        }
    }

    @PluginMethod
    fun disconnect(call: PluginCall) {
        VpnTunnelPlugin.pendingDisconnectCall = call
        val intent = Intent(context, SimpleDimpleVpnService::class.java).apply {
            action = SimpleDimpleVpnService.ACTION_STOP
        }
        context.startService(intent)
    }

    @PluginMethod
    fun status(call: PluginCall) {
        val result = JSObject()
        result.put("status", if (SimpleDimpleVpnService.isRunning) "connected" else "disconnected")
        call.resolve(result)
    }

    companion object {
        // Bridges SimpleDimpleVpnService (started via Intent, not directly
        // callable from here) back to the PluginCall that triggered it. Capacitor
        // plugin instances are not directly reachable from a Service, so the
        // service resolves/rejects through these static hooks instead.
        var pendingConnectCall: PluginCall? = null
        var pendingDisconnectCall: PluginCall? = null

        fun notifyTunnelStarted(success: Boolean, error: String?) {
            val call = pendingConnectCall ?: return
            pendingConnectCall = null
            if (success) {
                val result = JSObject()
                result.put("status", "connected")
                call.resolve(result)
            } else {
                call.reject(error ?: "failed to start tunnel")
            }
        }

        fun notifyTunnelStopped(success: Boolean, error: String?) {
            val call = pendingDisconnectCall ?: return
            pendingDisconnectCall = null
            if (success) {
                call.resolve(JSObject())
            } else {
                call.reject(error ?: "failed to stop tunnel")
            }
        }
    }
}

internal data class TunnelParams(
    val uuid: String,
    val address: String,
    val port: Int,
    val flow: String,
    val sni: String,
    val fingerprint: String,
    val publicKey: String,
    val shortId: String
)

// Builds an Xray-core JSON config: a single "tun" inbound (reads/writes the
// fd handed out by VpnService.Builder.establish(), see
// https://github.com/XTLS/Xray-core/blob/main/proxy/tun/README.md) and a
// single VLESS+REALITY outbound built from the connection config the backend
// issued. No routing rules needed — with exactly one outbound, Xray-core
// sends everything there by default.
internal fun buildXrayConfig(params: TunnelParams): String {
    val user = org.json.JSONObject().apply {
        put("id", params.uuid)
        put("encryption", "none")
        if (params.flow.isNotEmpty()) put("flow", params.flow)
    }
    val vnext = org.json.JSONObject().apply {
        put("address", params.address)
        put("port", params.port)
        put("users", org.json.JSONArray().put(user))
    }
    val outboundSettings = org.json.JSONObject().apply {
        put("vnext", org.json.JSONArray().put(vnext))
    }
    val realitySettings = org.json.JSONObject().apply {
        put("show", false)
        put("fingerprint", params.fingerprint)
        put("serverName", params.sni)
        put("publicKey", params.publicKey)
        put("shortId", params.shortId)
    }
    val streamSettings = org.json.JSONObject().apply {
        put("network", "tcp")
        put("security", "reality")
        put("realitySettings", realitySettings)
    }
    val outbound = org.json.JSONObject().apply {
        put("protocol", "vless")
        put("settings", outboundSettings)
        put("streamSettings", streamSettings)
    }
    val inboundSettings = org.json.JSONObject().apply {
        put("name", "xraytun0")
        put("mtu", 1500)
    }
    val inbound = org.json.JSONObject().apply {
        put("protocol", "tun")
        put("settings", inboundSettings)
    }
    val root = org.json.JSONObject().apply {
        // "debug" (not "warning") so a real-device retest of the still-open
        // "no traffic reaches the server" question (see docs/DECISIONS.md,
        // Decision 032) actually shows where the REALITY dial/handshake
        // stalls, instead of only "started"/"stopped" lines.
        put("log", org.json.JSONObject().put("loglevel", "debug"))
        put("inbounds", org.json.JSONArray().put(inbound))
        put("outbounds", org.json.JSONArray().put(outbound))
    }
    return root.toString()
}
